insert into public.countries (iso_a3,name,region,tagline,palette,active,sort_order) values ('ZWE','Zimbabwe','Southern Africa','Where the smoke thunders, granite balances, and the Zambezi writes in light.','["#2EC4B6","#F4D35E","#EE964B","#C2185B","#7BDFF2"]'::jsonb,true,1)
