insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media) values ('victoria-falls','ZWE','Victoria Falls','Mosi-oa-Tunya — “The Smoke that Thunders”','waterfall',-17.9243,25.8572,'The Zambezi drops into a narrow basalt chasm along a 1.7 km front on the Zimbabwe–Zambia border, throwing spray that can be seen from tens of kilometres away.','Often called the largest single sheet of falling water on Earth, combining its 1,708 m width with a drop of about 108 m. A UNESCO World Heritage Site since 1989; its spray feeds a rainforest that grows on the cliff edge in a dry savanna.','Width × drop','1,708 m × ~108 m',true,true,1,'{"color":"#7BDFF2","intensity":1,"motion":"cascade"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/0/0a/Victoria_Falls_2019_8.webm/Victoria_Falls_2019_8.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/0/0a/Victoria_Falls_2019_8.webm/Victoria_Falls_2019_8.webm.360p.mpeg4.mov","credit":"Nesnad","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Victoria_Falls_2019_8.webm"}'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media) values ('batoka-gorge','ZWE','Batoka Gorge',null,'gorge',-17.98,25.92,'Below Victoria Falls the Zambezi zig-zags through a chain of sheer basalt gorges, carved as the falls retreated upstream over thousands of years.','Each zig-zag records a former position of the waterfall, so the gorge works like a timeline written in rock. Its rapids rank among the world''s great whitewater runs.','Length','~120 km',false,true,2,'{"color":"#2EC4B6","intensity":0.7,"motion":"zigzag"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/52/Video_-_Above_Victoria_Falls.webm/Video_-_Above_Victoria_Falls.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/52/Video_-_Above_Victoria_Falls.webm/Video_-_Above_Victoria_Falls.webm.360p.mpeg4.mov","credit":"Mike","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Video_-_Above_Victoria_Falls.webm","note":"Stand-in: flight over the falls and the first gorges"}'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media) values ('mana-pools','ZWE','Mana Pools','Mana — “four” in Shona, for its four main pools','wetland',-15.8,29.4,'A wild Zambezi floodplain of oxbow pools and ana-tree woodland, where elephants stand on their hind legs to reach the branches.','A UNESCO natural World Heritage Site (1984, with Sapi and Chewore). One of the few parks in Africa where guided walking among big game is permitted.','UNESCO','1984',true,true,3,'{"color":"#F4D35E","intensity":0.8,"motion":"ripple"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/a/af/Boswell_by_the_Zambezi_river.webm/Boswell_by_the_Zambezi_river.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/a/af/Boswell_by_the_Zambezi_river.webm/Boswell_by_the_Zambezi_river.webm.360p.mpeg4.mov","credit":"Lennart Hessel","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Boswell_by_the_Zambezi_river.webm","note":"Boswell — the bull elephant famous for standing on his hind legs"}'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media) values ('hwange','ZWE','Hwange National Park',null,'savanna',-18.9,26.5,'Zimbabwe''s largest park: Kalahari sandveld, teak forest and pans, home to one of Africa''s largest elephant populations.','Life at Hwange gathers around its waterholes. In the dry season, herds of hundreds of elephants come to them at dusk.','Area','~14,650 km²',false,true,4,'{"color":"#EE964B","intensity":0.9,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/d/de/Elephants%2C_Mana_Pools_National_Park.webm/Elephants%2C_Mana_Pools_National_Park.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/d/de/Elephants%2C_Mana_Pools_National_Park.webm/Elephants%2C_Mana_Pools_National_Park.webm.360p.mpeg4.mov","credit":"Lennart Hessel","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Elephants,_Mana_Pools_National_Park.webm","start":10,"note":"Stand-in: elephant herd in Mana Pools, until Hwange footage is added"}'::jsonb)
