insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media) values ('matobo-hills','ZWE','Matobo Hills','Matopos — “bald heads”','rock',-20.55,28.5,'A sea of granite kopjes, whalebacks and balancing boulders, weathered from rock that formed over 2 billion years ago.','A UNESCO World Heritage Site since 2003. It has one of the densest concentrations of rock art in southern Africa and one of the highest densities of black eagles and rhinos.','Granite age','> 2 billion yrs',true,true,5,'{"color":"#C2185B","intensity":0.85,"motion":"orbit"}'::jsonb,'{}'::jsonb)
