insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media) values ('chinhoyi-caves','ZWE','Chinhoyi Caves','Chirorodziva — “Pool of the Fallen”','cave',-17.355,30.125,'Limestone and dolomite caverns around a collapsed sinkhole holding the Sleeping Pool, a body of water that glows an unreal cobalt blue.','The pool''s clarity and its constant temperature of about 22 °C make it a famous cave-diving site. Its depths run past 80 m into flooded passages.','Water temp','~22 °C year-round',false,true,6,'{"color":"#3A86FF","intensity":0.9,"motion":"sink"}'::jsonb,'{}'::jsonb)
