insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media) values ('mutarazi-falls','ZWE','Mutarazi Falls',null,'waterfall',-18.53,32.8,'A thin ribbon of water that drops off the Eastern Highlands escarpment into the Honde Valley in two tiers.','Zimbabwe''s highest waterfall at about 762 m, often cited as the second-highest in Africa. A skywalk and zipline now hang over the drop.','Total drop','~762 m',false,true,7,'{"color":"#A8DADC","intensity":0.75,"motion":"cascade"}'::jsonb,'{}'::jsonb)
