insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media) values ('mount-nyangani','ZWE','Mount Nyangani',null,'mountain',-18.3,32.85,'A misty moorland plateau in Nyanga National Park and the source of rivers that flow toward both the Zambezi and the Indian Ocean.','The highest point in Zimbabwe. Local lore holds that the mountain ''swallows'' hikers, and its fast-changing mist has made that legend very easy to believe.','Elevation','2,592 m',false,true,8,'{"color":"#B8B8FF","intensity":0.7,"motion":"mist"}'::jsonb,'{}'::jsonb)
