insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media) values ('chilojo-cliffs','ZWE','Chilojo Cliffs, Gonarezhou','Gonarezhou — “Place of Elephants”','rock',-21.65,31.75,'Banded red-and-ochre sandstone cliffs rising high above the Runde River in Gonarezhou National Park.','Iconic of Zimbabwe''s southeast lowveld, the cliffs blaze crimson at sunset. They''re part of the Great Limpopo Transfrontier Park, which links Zimbabwe, South Africa and Mozambique.','Height','up to ~180 m',false,true,10,'{"color":"#E63946","intensity":0.85,"motion":"ripple"}'::jsonb,'{}'::jsonb)
