insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media) values ('epworth-balancing-rocks','ZWE','Epworth Balancing Rocks',null,'rock',-17.89,31.15,'Granite boulders stacked in impossible-looking towers just outside Harare, shaped by millions of years of weathering.','They once appeared on Zimbabwe''s banknotes, a natural sculpture garden that seems to defy gravity.','Near','Harare',false,true,11,'{"color":"#FFB703","intensity":0.6,"motion":"orbit"}'::jsonb,'{}'::jsonb)
